
DROP SCHEMA IF EXISTS erp CASCADE;
CREATE SCHEMA erp;
SET search_path TO erp;

-- ============================================================
-- 1. CADASTROS / DADOS MESTRES
-- ============================================================

CREATE TABLE estado (
    id_estado SERIAL PRIMARY KEY,
    uf VARCHAR(4) NOT NULL,
    nome VARCHAR(80) NOT NULL,
    regiao VARCHAR(20)
);

CREATE TABLE cidade (
    id_cidade SERIAL PRIMARY KEY,
    nome VARCHAR(120) NOT NULL,
    id_estado INTEGER NOT NULL REFERENCES estado(id_estado)
);

CREATE TABLE filial (
    id_filial SERIAL PRIMARY KEY,
    nome VARCHAR(120) NOT NULL,
    tipo VARCHAR(20),
    cnpj VARCHAR(30),
    telefone VARCHAR(40),
    email VARCHAR(160),
    logradouro VARCHAR(160),
    numero VARCHAR(10),
    bairro VARCHAR(100),
    cep VARCHAR(12),
    id_cidade INTEGER NOT NULL REFERENCES cidade(id_cidade),
    data_abertura DATE
);

CREATE TABLE cliente (
    id_cliente SERIAL PRIMARY KEY,
    nome_razao VARCHAR(150) NOT NULL,
    tipo_pessoa CHAR(1) NOT NULL,
    cpf_cnpj VARCHAR(30),
    data_nascimento DATE,
    sexo CHAR(1),
    segmento VARCHAR(30),
    email VARCHAR(160),
    telefone VARCHAR(40),
    logradouro VARCHAR(160),
    numero VARCHAR(10),
    bairro VARCHAR(100),
    cep VARCHAR(12),
    id_cidade INTEGER REFERENCES cidade(id_cidade),
    canal_origem VARCHAR(40),
    limite_credito NUMERIC(12,2),
    data_cadastro DATE,
    ativo BOOLEAN DEFAULT TRUE
);

CREATE TABLE fornecedor (
    id_fornecedor SERIAL PRIMARY KEY,
    razao_social VARCHAR(160) NOT NULL,
    cnpj VARCHAR(30),
    email VARCHAR(160),
    telefone VARCHAR(40),
    contato_nome VARCHAR(120),
    logradouro VARCHAR(160),
    numero VARCHAR(10),
    bairro VARCHAR(100),
    cep VARCHAR(12),
    id_cidade INTEGER REFERENCES cidade(id_cidade),
    prazo_entrega_dias INTEGER,
    ativo BOOLEAN DEFAULT TRUE
);

CREATE TABLE unidade_medida (
    id_unidade SERIAL PRIMARY KEY,
    sigla VARCHAR(10) NOT NULL,
    descricao VARCHAR(80) NOT NULL
);

CREATE TABLE categoria_produto (
    id_categoria SERIAL PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    id_categoria_pai INTEGER REFERENCES categoria_produto(id_categoria)
);

CREATE TABLE produto (
    id_produto SERIAL PRIMARY KEY,
    sku VARCHAR(30) NOT NULL,
    nome VARCHAR(160) NOT NULL,
    marca VARCHAR(80),
    id_categoria INTEGER NOT NULL REFERENCES categoria_produto(id_categoria),
    id_unidade INTEGER NOT NULL REFERENCES unidade_medida(id_unidade),
    id_fornecedor_principal INTEGER REFERENCES fornecedor(id_fornecedor),
    peso_kg NUMERIC(8,3),
    custo_padrao NUMERIC(12,2),
    preco_venda NUMERIC(12,2),
    estoque_minimo NUMERIC(12,3),
    ativo BOOLEAN DEFAULT TRUE
);

CREATE TABLE lote_produto (
    id_lote SERIAL PRIMARY KEY,
    id_produto INTEGER NOT NULL REFERENCES produto(id_produto),
    numero_lote VARCHAR(40) NOT NULL,
    data_fabricacao DATE,
    data_validade DATE,
    quantidade_inicial NUMERIC(12,3) NOT NULL
);

-- ============================================================
-- 2. RH
-- ============================================================

CREATE TABLE departamento (
    id_departamento SERIAL PRIMARY KEY,
    nome VARCHAR(100) NOT NULL
);

CREATE TABLE cargo (
    id_cargo SERIAL PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    nivel VARCHAR(30),
    faixa_salarial_min NUMERIC(12,2),
    faixa_salarial_max NUMERIC(12,2)
);

CREATE TABLE funcionario (
    id_funcionario SERIAL PRIMARY KEY,
    nome VARCHAR(150) NOT NULL,
    cpf VARCHAR(30),
    pis VARCHAR(20),
    sexo CHAR(1),
    estado_civil VARCHAR(20),
    email VARCHAR(160),
    telefone VARCHAR(40),
    data_nascimento DATE,
    data_admissao DATE NOT NULL,
    data_demissao DATE,
    tipo_contrato VARCHAR(20),
    carga_horaria_semanal INTEGER,
    salario_base NUMERIC(12,2),
    id_departamento INTEGER NOT NULL REFERENCES departamento(id_departamento),
    id_cargo INTEGER NOT NULL REFERENCES cargo(id_cargo),
    id_filial INTEGER NOT NULL REFERENCES filial(id_filial),
    id_cidade INTEGER REFERENCES cidade(id_cidade),
    ativo BOOLEAN DEFAULT TRUE
);

CREATE TABLE meta_vendedor (
    id_meta SERIAL PRIMARY KEY,
    id_funcionario INTEGER NOT NULL REFERENCES funcionario(id_funcionario),
    competencia DATE NOT NULL,
    meta_valor NUMERIC(12,2) NOT NULL
);

CREATE TABLE folha_pagamento (
    id_folha SERIAL PRIMARY KEY,
    id_funcionario INTEGER NOT NULL REFERENCES funcionario(id_funcionario),
    competencia DATE NOT NULL,
    salario_base NUMERIC(12,2) NOT NULL,
    horas_extras NUMERIC(8,2) DEFAULT 0,
    valor_horas_extras NUMERIC(12,2) DEFAULT 0,
    bonus NUMERIC(12,2) DEFAULT 0,
    inss NUMERIC(12,2) DEFAULT 0,
    irrf NUMERIC(12,2) DEFAULT 0,
    fgts NUMERIC(12,2) DEFAULT 0,
    descontos NUMERIC(12,2) DEFAULT 0
);

CREATE TABLE registro_ponto (
    id_ponto SERIAL PRIMARY KEY,
    id_funcionario INTEGER NOT NULL REFERENCES funcionario(id_funcionario),
    data DATE NOT NULL,
    entrada TIME,
    saida TIME,
    justificativa VARCHAR(120)
);

-- ============================================================
-- 3. VENDAS
-- ============================================================

CREATE TABLE pedido_venda (
    id_pedido SERIAL PRIMARY KEY,
    data_pedido TIMESTAMP NOT NULL,
    id_cliente INTEGER NOT NULL REFERENCES cliente(id_cliente),
    id_vendedor INTEGER NOT NULL REFERENCES funcionario(id_funcionario),
    id_filial INTEGER NOT NULL REFERENCES filial(id_filial),
    status VARCHAR(40) NOT NULL,
    canal VARCHAR(40),
    prazo_entrega_dias INTEGER,
    desconto_pedido NUMERIC(12,2) DEFAULT 0,
    observacao VARCHAR(250)
);

CREATE TABLE item_pedido_venda (
    id_item SERIAL PRIMARY KEY,
    id_pedido INTEGER NOT NULL REFERENCES pedido_venda(id_pedido),
    id_produto INTEGER NOT NULL REFERENCES produto(id_produto),
    quantidade NUMERIC(12,3) NOT NULL,
    preco_unitario NUMERIC(12,2),
    desconto_item NUMERIC(12,2) DEFAULT 0
);

CREATE TABLE pagamento_venda (
    id_pagamento SERIAL PRIMARY KEY,
    id_pedido INTEGER NOT NULL REFERENCES pedido_venda(id_pedido),
    forma_pagamento VARCHAR(50) NOT NULL,
    bandeira_cartao VARCHAR(30),
    parcelas INTEGER DEFAULT 1,
    valor NUMERIC(12,2) NOT NULL,
    data_pagamento DATE,
    status VARCHAR(40) NOT NULL
);

CREATE TABLE devolucao_venda (
    id_devolucao SERIAL PRIMARY KEY,
    id_pedido INTEGER NOT NULL REFERENCES pedido_venda(id_pedido),
    id_produto INTEGER NOT NULL REFERENCES produto(id_produto),
    data_devolucao DATE NOT NULL,
    quantidade NUMERIC(12,3) NOT NULL,
    motivo VARCHAR(120),
    valor_devolvido NUMERIC(12,2),
    status VARCHAR(40)
);

CREATE TABLE avaliacao_pedido (
    id_avaliacao SERIAL PRIMARY KEY,
    id_pedido INTEGER NOT NULL REFERENCES pedido_venda(id_pedido),
    nota INTEGER,
    comentario VARCHAR(250),
    data_avaliacao DATE
);

-- ============================================================
-- 4. COMPRAS
-- ============================================================

CREATE TABLE pedido_compra (
    id_pedido_compra SERIAL PRIMARY KEY,
    data_pedido DATE NOT NULL,
    data_prevista_entrega DATE,
    id_fornecedor INTEGER NOT NULL REFERENCES fornecedor(id_fornecedor),
    id_comprador INTEGER NOT NULL REFERENCES funcionario(id_funcionario),
    id_filial INTEGER NOT NULL REFERENCES filial(id_filial),
    condicao_pagamento VARCHAR(40),
    status VARCHAR(40) NOT NULL
);

CREATE TABLE item_pedido_compra (
    id_item_compra SERIAL PRIMARY KEY,
    id_pedido_compra INTEGER NOT NULL REFERENCES pedido_compra(id_pedido_compra),
    id_produto INTEGER NOT NULL REFERENCES produto(id_produto),
    quantidade NUMERIC(12,3) NOT NULL,
    custo_unitario NUMERIC(12,2) NOT NULL
);

CREATE TABLE conta_pagar (
    id_conta_pagar SERIAL PRIMARY KEY,
    id_pedido_compra INTEGER NOT NULL REFERENCES pedido_compra(id_pedido_compra),
    data_emissao DATE NOT NULL,
    data_vencimento DATE NOT NULL,
    valor NUMERIC(12,2) NOT NULL,
    status VARCHAR(40) NOT NULL,
    data_baixa DATE
);

-- ============================================================
-- 5. ESTOQUE
-- ============================================================

CREATE TABLE deposito (
    id_deposito SERIAL PRIMARY KEY,
    nome VARCHAR(120) NOT NULL,
    capacidade_m3 NUMERIC(10,2),
    id_filial INTEGER NOT NULL REFERENCES filial(id_filial)
);

CREATE TABLE movimento_estoque (
    id_movimento SERIAL PRIMARY KEY,
    data_movimento TIMESTAMP NOT NULL,
    id_produto INTEGER NOT NULL REFERENCES produto(id_produto),
    id_lote INTEGER REFERENCES lote_produto(id_lote),
    id_deposito INTEGER NOT NULL REFERENCES deposito(id_deposito),
    tipo_movimento VARCHAR(30) NOT NULL,
    quantidade NUMERIC(12,3) NOT NULL,
    id_pedido_venda INTEGER REFERENCES pedido_venda(id_pedido),
    id_pedido_compra INTEGER REFERENCES pedido_compra(id_pedido_compra),
    observacao VARCHAR(250)
);

-- ============================================================
-- 6. LOGISTICA
-- ============================================================

CREATE TABLE transportadora (
    id_transportadora SERIAL PRIMARY KEY,
    razao_social VARCHAR(160) NOT NULL,
    cnpj VARCHAR(30),
    telefone VARCHAR(40),
    email VARCHAR(160)
);

CREATE TABLE veiculo (
    id_veiculo SERIAL PRIMARY KEY,
    id_transportadora INTEGER NOT NULL REFERENCES transportadora(id_transportadora),
    placa VARCHAR(15) NOT NULL,
    tipo VARCHAR(50),
    capacidade_kg NUMERIC(12,2)
);

CREATE TABLE entrega (
    id_entrega SERIAL PRIMARY KEY,
    id_pedido INTEGER NOT NULL REFERENCES pedido_venda(id_pedido),
    id_transportadora INTEGER REFERENCES transportadora(id_transportadora),
    id_veiculo INTEGER REFERENCES veiculo(id_veiculo),
    id_motorista INTEGER REFERENCES funcionario(id_funcionario),
    data_saida TIMESTAMP,
    data_prevista DATE,
    data_entrega TIMESTAMP,
    status VARCHAR(40) NOT NULL,
    valor_frete NUMERIC(12,2)
);

CREATE TABLE ocorrencia_entrega (
    id_ocorrencia SERIAL PRIMARY KEY,
    id_entrega INTEGER NOT NULL REFERENCES entrega(id_entrega),
    data_ocorrencia TIMESTAMP NOT NULL,
    tipo VARCHAR(60),
    descricao VARCHAR(250)
);

-- ============================================================
-- 7. FINANCEIRO (conta_receber)
-- ============================================================

CREATE TABLE conta_receber (
    id_conta_receber SERIAL PRIMARY KEY,
    id_pedido INTEGER NOT NULL REFERENCES pedido_venda(id_pedido),
    data_emissao DATE NOT NULL,
    data_vencimento DATE NOT NULL,
    valor NUMERIC(12,2) NOT NULL,
    forma_pagamento VARCHAR(50),
    status VARCHAR(40) NOT NULL,
    data_baixa DATE
);

